export function saveState(state: RunState): void {
  state.updatedAt = new Date().toISOString();
  const path = statePath(state.runId);
  mkdirSync(dirname(path), { recursive: true });
  writeFileSync(path, `${JSON.stringify(state, null, 2)}\n`);
}

export async function runCrew(options: CliOptions): Promise<RunResult> {
  const goal = buildGoal(options);
  const existing = options.resume ? loadState(options.resume) : undefined;
  const runId = existing?.runId ?? options.runId ?? newRunId();
  const localTracePath = join(runDir(runId), "trace.jsonl");
  startLocalTrace(localTracePath);

  const exported = await initTelemetry("releasecrew");
  const llm = describeLlm();

  const state: RunState =
    existing ??
    {
      runId,
      createdAt: new Date().toISOString(),
      updatedAt: new Date().toISOString(),
      goal,
      demoFailures: options.demoFailures,
      completed: [],
      failures: [],
      usage: currentUsage(),
      localTracePath,
    };

  state.goal = goal;
  state.demoFailures = options.demoFailures;
  saveState(state);

  try {
    const result = await withWorkflow("releasecrew.run", async () => {
      neatlog("Starting ReleaseCrew {repo} {tag} llm={llm} neatlogs={neatlogs}", {
        repo: goal.repo,
        tag: goal.tag,
        llm: llm.mode,
        neatlogs: exported.exported ? "exporting" : "local-only",
      });

      if (!isComplete(state, "plan")) {
        state.plan = await planRelease(goal);
        markComplete(state, "plan");
      }

      if (!isComplete(state, "research")) {
        try {
          state.research = await researchRelease(goal, options.demoFailures);
          if (options.demoFailures) {
            recordFailure(state, {
              step: "research",
              kind: "rate_limit",
              message: "GitHub API rate limit (demo 429) — retried and recovered",
              recovered: true,
            });
          }
          markComplete(state, "research");
        } catch (error) {
          recordFailure(state, {
            step: "research",
            kind: "rate_limit",
            message: error instanceof Error ? error.message : String(error),
            recovered: false,
          });
          throw error;
        }
      }

      if (!state.research) throw new Error("research bundle missing");

      if (!isComplete(state, "write") || !isComplete(state, "verify")) {
        let attempt = state.draft?.attempt ?? 0;
        let passed = false;
        while (!passed && attempt < 3) {
          attempt += 1;
          const inject = options.demoFailures && attempt === 1;
          state.draft = await writeReleaseStory(
            goal,
            state.research,
            state.verification?.feedback,
            attempt,
            inject,
          );
          state.verification = await verifyDraft(state.research, state.draft, attempt);
          passed = state.verification.passed;
          if (!passed) {
            recordFailure(state, {
              step: "verify",
              kind: "bad_model_output",
              message: state.verification.feedback,
              recovered: attempt < 3,
            });
          }
        }
        if (!state.verification?.passed) {
          throw new Error(`verifier rejected the draft after ${attempt} attempts`);
        }
        markComplete(state, "write");
        markComplete(state, "verify");
      }

      if (!isComplete(state, "media")) {
        if (!state.draft || !state.verification) throw new Error("draft or verification missing");
        try {
          state.media = await produceMedia(
            goal,
            state.research,
            state.draft,
            state.verification,
            runDir(runId),
            options.demoFailures,
          );
          if (options.demoFailures) {
            recordFailure(state, {
              step: "media",
              kind: "render_failure",
              message: "ffmpeg encoder failed on first attempt — recovered with retry/fallback",
              recovered: true,
            });
          }
          markComplete(state, "media");
        } catch (error) {
          recordFailure(state, {
            step: "media",
            kind: "render_failure",
            message: error instanceof Error ? error.message : String(error),
            recovered: false,
          });
          throw error;
        }
      }

      const manifest = writeKit(state);
      markComplete(state, "assemble");
      state.usage = currentUsage();
      saveState(state);
      return { state, manifest, summary: summarizeTrace() };
    });
    return result;
  } finally {
    await flushTelemetry();
  }
}

export async function planRelease(goal: Goal): Promise<Plan> {
  return withAgent(
    "planner",
    "planner",
    `Ship a verified release kit for ${goal.repo}@${goal.tag}`,
    async () => {
      const llm = describeLlm();
      if (llm.mode === "heuristic") {
        const plan = heuristicPlan(goal);
        estimateHeuristicUsage(JSON.stringify(plan).length);
        return plan;
      }
      const result = await generateStructured({
        name: "planner.decompose",
        schema: planSchema,
        system:
          "You are the planner for ReleaseCrew. Break a GitHub release-kit goal into concrete agent steps. Do not invent product features.",
        user: `Repo ${goal.repo}, tag ${goal.tag}, from ${goal.from ?? "previous release"}. Output a plan with research, write, verify, media, assemble.`,
      });
      return result.value;
    },
  );
}

export async function researchRelease(goal: Goal, demoFailures: boolean): Promise<ResearchBundle> {
  return withAgent(
    "researcher",
    "researcher",
    `Build a structured change list for ${goal.repo}@${goal.tag}`,
    async () => {
      const github = new GithubClient({ demoFailures });
      const release = await github.releaseByTag(goal.owner, goal.name, goal.tag);
      const previousTag = goal.from ?? (await inferPreviousTag(github, goal, release?.tag ?? goal.tag));
      const compare = previousTag
        ? await github.compare(goal.owner, goal.name, previousTag, goal.tag)
        : { commits: [], files: [], additions: 0, deletions: 0, htmlUrl: "" };

      const pulls = await withTool("github.searchPulls", async () => {
        if (!previousTag) return [];
        return github.searchPulls(goal.owner, goal.name, `${previousTag}..${goal.tag}`);
      }).catch(() => []);

      const changes = buildChanges(goal, compare.commits, pulls);
      const issues = pulls
        .flatMap((pull) => {
          const body = String(pull.body ?? "");
          const matches = body.match(/#(\d+)/g) ?? [];
          return matches.slice(0, 3).map((match) => ({
            number: Number(match.slice(1)),
            title: `Linked from PR #${pull.number}`,
            url: `https://github.com/${goal.repo}/issues/${match.slice(1)}`,
          }));
        })
        .slice(0, 12);

      return {
        repo: goal.repo,
        tag: goal.tag,
        compareRange: previousTag ? `${previousTag}...${goal.tag}` : goal.tag,
        previousTag,
        release,
        commits: compare.commits.map((commit) => ({
          sha: commit.sha,
          message: commit.message,
          author: commit.author,
          url: commit.url,
        })),
        pullRequests: pulls.map((pull) => ({
          number: Number(pull.number),
          title: String(pull.title ?? ""),
          body: String(pull.body ?? "").slice(0, 1200),
          url: String(pull.html_url ?? `https://github.com/${goal.repo}/pull/${pull.number}`),
          files: [],
        })),
        issues,
        filesChanged: compare.files.map((file) => file.filename),
        stats: {
          commits: compare.commits.length,
          files: compare.files.length,
          additions: compare.additions,
          deletions: compare.deletions,
          pullRequests: pulls.length,
        },
        changes,
      };
    },
  );
}

export async function writeReleaseStory(
  goal: Goal,
  research: ResearchBundle,
  feedback?: string,
  attempt = 1,
  injectHallucination = false,
): Promise<Draft> {
  return withAgent(
    "writer",
    "writer",
    `Draft release notes and a launch thread for ${goal.repo}@${goal.tag}`,
    async () => {
      const llm = describeLlm();
      const base =
        llm.mode === "llm"
          ? await llmDraft(goal, research, feedback)
          : heuristicDraft(goal, research, feedback);
      const notes = injectHallucination ? poisonNotes(base.notes) : base.notes;
      const thread = injectHallucination ? poisonThread(base.thread) : base.thread;
      estimateHeuristicUsage(notes.markdown.length + thread.tweets.join("").length);
      return {
        notes,
        thread,
        attempt,
        provider: llm.provider,
        model: llm.model,
      };
    },
  );
}
